<template>
  <el-dialog :model-value="modelValue" title="缺陷管理中心" width="min(1080px, 96vw)" top="4vh" class="defect-management-dialog" @update:model-value="emit('update:modelValue', $event)">
    <el-alert v-if="!projectId" title="请先选择一个项目，再使用指标、视图、导入导出和工作流配置。" type="info" :closable="false" />
    <el-tabs v-else v-model="tab" @tab-change="tabChanged">
      <el-tab-pane label="指标看板" name="metrics">
        <div v-loading="loadingMetrics">
          <div class="metric-cards"><el-card v-for="item in metricCards" :key="item.label" shadow="never"><span>{{ item.label }}</span><strong>{{ item.value }}</strong><small>{{ item.hint }}</small></el-card></div>
          <el-alert v-if="metrics?.data_quality" :title="metrics.data_quality.message" :type="metrics.data_quality.history_complete ? 'success' : 'warning'" :closable="false" />
          <h3>近 {{ metrics?.period?.days || 30 }} 天趋势</h3>
          <el-table :data="metrics?.trend || []" max-height="320" size="small"><el-table-column prop="date" label="日期"/><el-table-column prop="created" label="新增"/><el-table-column prop="resolved" label="验证解决"/><el-table-column prop="reopened" label="重开"/><el-table-column prop="closed" label="关闭"/></el-table>
        </div>
      </el-tab-pane>
      <el-tab-pane label="保存视图" name="views">
        <div class="section-toolbar"><div><b>团队筛选视图</b><p>保存当前筛选条件，可设为个人视图或项目共享视图。</p></div><el-button type="primary" @click="saveCurrentView">保存当前筛选</el-button></div>
        <el-table :data="savedViews" empty-text="暂无保存视图"><el-table-column prop="name" label="视图名称"/><el-table-column label="范围" width="110"><template #default="{ row }">{{ row.visibility === 'project' ? '项目共享' : '仅自己' }}</template></el-table-column><el-table-column label="操作" width="170"><template #default="{ row }"><el-button link type="primary" @click="applyView(row)">应用</el-button><el-button v-if="row.owner_id === auth.user?.id || canConfigure" link type="danger" @click="removeView(row)">删除</el-button></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane label="导入导出" name="transfer">
        <div class="transfer-grid">
          <el-card shadow="never"><template #header><b>批量导入</b></template><p>先预览校验，再提交有效行。支持 CSV 和 XLSX，最多 5000 条。</p><div class="button-row"><el-button @click="downloadTemplate">下载模板</el-button><label class="file-button"><input type="file" accept=".csv,.xlsx" @change="previewFile"/><span>{{ previewing ? '解析中…' : '选择文件并预览' }}</span></label></div><div v-if="importPreview" class="import-summary"><el-alert :title="`共 ${importPreview.total} 行，有效 ${importPreview.valid} 行，错误 ${importPreview.invalid} 行`" :type="importPreview.invalid ? 'warning' : 'success'" :closable="false"/><el-table :data="importPreview.rows" max-height="280" size="small"><el-table-column prop="row_number" label="行" width="55"/><el-table-column label="标题" min-width="160"><template #default="{ row }">{{ row.data.title }}</template></el-table-column><el-table-column label="校验" min-width="220"><template #default="{ row }"><span v-if="row.errors.length" class="error-text">{{ row.errors.join('；') }}</span><span v-else-if="row.warnings.length" class="warning-text">{{ row.warnings.join('；') }}</span><span v-else class="success-text">可导入</span></template></el-table-column></el-table><el-button type="primary" :loading="committing" :disabled="!importPreview.valid" @click="commitImport">导入全部有效行</el-button></div></el-card>
          <el-card shadow="never"><template #header><b>安全导出</b></template><p>导出当前选中缺陷；未选择时按当前项目筛选导出。文件 7 天后过期。</p><el-radio-group v-model="exportFormat"><el-radio-button value="xlsx">Excel</el-radio-button><el-radio-button value="csv">CSV</el-radio-button></el-radio-group><p class="muted">{{ selectedIds.length ? `已选择 ${selectedIds.length} 条` : '未选择行，将按当前筛选导出' }}</p><el-button type="primary" :loading="exporting" @click="exportData">生成并下载</el-button></el-card>
        </div>
      </el-tab-pane>
      <el-tab-pane label="项目配置" name="settings">
        <el-form v-if="settingsForm" label-position="top" class="settings-form">
          <el-form-item label="指标与日期时区"><el-select v-model="settingsForm.timezone"><el-option label="中国标准时间 (Asia/Shanghai)" value="Asia/Shanghai"/><el-option label="UTC" value="UTC"/><el-option label="东京 (Asia/Tokyo)" value="Asia/Tokyo"/><el-option label="纽约 (America/New_York)" value="America/New_York"/></el-select></el-form-item>
          <el-form-item label="新建必填字段"><el-select v-model="settingsForm.field_config.required_on_create" multiple allow-create filterable><el-option label="所属模块" value="module_id"/><el-option label="测试环境" value="environment_profile_id"/><el-option label="复现步骤" value="reproduce_steps"/><el-option label="预期结果" value="expected_result"/><el-option label="实际结果" value="actual_result"/></el-select></el-form-item>
          <el-form-item label="完成分诊前必填字段"><el-select v-model="settingsForm.field_config.required_on_triage" multiple filterable><el-option label="所属模块" value="module_id"/><el-option label="所属迭代" value="iteration_id"/><el-option label="测试环境" value="environment_profile_id"/><el-option label="处理人" value="assignee_id"/><el-option label="验证人" value="verifier_id"/></el-select></el-form-item>
          <div class="switch-grid"><el-form-item label="报告人可编辑自己登记的缺陷"><el-switch v-model="settingsForm.permission_config.allow_reporter_edit"/></el-form-item><el-form-item label="开发可编辑指派给自己的缺陷"><el-switch v-model="settingsForm.permission_config.allow_developer_edit_assigned"/></el-form-item></div>
          <el-form-item label="通知事件"><el-select v-model="settingsForm.notification_config.enabled_events" multiple allow-create filterable><el-option label="全部事件" value="*"/><el-option label="评论" value="comment_added"/><el-option label="指派" value="assigned"/><el-option label="提交修复" value="submit_fix"/><el-option label="验证结果" value="verify_pass"/></el-select></el-form-item>
          <el-form-item label="默认关注人"><el-select v-model="settingsForm.notification_config.default_watchers" multiple filterable><el-option v-for="item in settingParticipants" :key="item.id" :label="item.username" :value="item.id"/></el-select></el-form-item>
          <el-form-item label="通知操作者本人"><el-switch v-model="settingsForm.notification_config.notify_actor"/></el-form-item>
          <el-button type="primary" :loading="savingSettings" :disabled="!canConfigure" @click="saveSettings">保存项目配置</el-button>
        </el-form>
      </el-tab-pane>
      <el-tab-pane label="自定义工作流" name="workflow">
        <el-alert title="发布新版本只影响之后新建的缺陷；已有缺陷需先预览并执行显式迁移。已发布版本不可修改。" type="info" :closable="false" />
        <div class="section-toolbar"><el-select v-model="workflowId" placeholder="选择工作流" @change="selectWorkflow"><el-option v-for="item in workflows" :key="item.id" :label="item.name" :value="item.id"/></el-select><div class="button-row"><el-button :disabled="!canConfigure" @click="createWorkflow">新建工作流</el-button><el-button :disabled="!workflowId || !canConfigure" @click="createDraft">创建 / 打开草稿</el-button><el-button :disabled="!activeRevisionId || !canConfigure" @click="migrateExisting">迁移已有缺陷</el-button></div></div>
        <template v-if="draft"><el-input v-model="definitionText" type="textarea" :rows="18" spellcheck="false" aria-label="工作流 JSON 定义"/><div class="button-row"><el-button :loading="savingDraft" @click="saveDraft">校验并保存草稿</el-button><el-button type="primary" :loading="publishing" @click="publishDraft">发布此版本</el-button></div></template>
        <el-empty v-else description="选择工作流并创建草稿后编辑" :image-size="70"/>
      </el-tab-pane>
    </el-tabs>
  </el-dialog>
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { defectsApi } from '@/api'
import { useAuthStore } from '@/stores'
import { createRequestId } from '@/utils/requestId'
const props = defineProps<{ modelValue: boolean; projectId: string; filters: Record<string, any>; selectedIds: string[]; canConfigure: boolean }>()
const emit = defineEmits<{ 'update:modelValue': [boolean]; applyView: [Record<string, any>]; refreshed: [] }>()
const auth = useAuthStore(), tab = ref('metrics'), metrics = ref<any>(), loadingMetrics = ref(false), savedViews = ref<any[]>([])
const importPreview = ref<any>(), importJobId = ref(''), previewing = ref(false), committing = ref(false), exporting = ref(false), exportFormat = ref('xlsx')
const settingsForm = ref<any>(), savingSettings = ref(false), settingParticipants = ref<any[]>([]), workflows = ref<any[]>([]), workflowId = ref(''), draft = ref<any>(), definitionText = ref(''), savingDraft = ref(false), publishing = ref(false)
const activeRevisionId = computed(() => workflows.value.find(item => item.id === workflowId.value)?.active_revision_id || '')
const metricCards = computed(() => { const value = metrics.value?.summary || {}; return [
  { label: '当前积压', value: value.backlog ?? '—', hint: `其中逾期 ${value.overdue ?? '—'} 个` },
  { label: '期间验证解决', value: value.resolved_in_period ?? '—', hint: `重开 ${value.reopened_in_period ?? '—'} 次` },
  { label: '平均修复时效', value: value.mean_time_to_resolve_hours == null ? '无完整数据' : `${value.mean_time_to_resolve_hours}h`, hint: '创建至首次验证通过' },
  { label: '首次响应', value: value.mean_first_response_hours == null ? '无完整数据' : `${value.mean_first_response_hours}h`, hint: '创建至首个处理事件' },
]})
watch(() => [props.modelValue, props.projectId], () => { if (props.modelValue && props.projectId) void loadMetrics() }, { immediate: true })
async function tabChanged(name: string | number) { if (name === 'metrics') await loadMetrics(); if (name === 'views') await loadViews(); if (name === 'settings') await loadSettings(); if (name === 'workflow') await loadWorkflows() }
async function loadMetrics() { loadingMetrics.value = true; try { const res: any = await defectsApi.metrics(props.projectId); metrics.value = res.data } finally { loadingMetrics.value = false } }
async function loadViews() { const res: any = await defectsApi.savedViews(props.projectId); savedViews.value = res.data.items }
async function saveCurrentView() { const result: any = await ElMessageBox.prompt('请输入视图名称', '保存筛选视图', { inputValidator: (v: string) => !!v.trim() || '请输入名称' }); const visibility = await ElMessageBox.confirm('是否保存为项目共享视图？', '视图范围', { confirmButtonText: '项目共享', cancelButtonText: '仅自己', distinguishCancelAndClose: true }).then(() => 'project').catch((action: string) => action === 'cancel' ? 'private' : Promise.reject(action)); await defectsApi.createView(props.projectId, { name: result.value, visibility, query: props.filters, columns: [], sort: [{ field: 'updated_at', direction: 'desc' }] }); await loadViews(); ElMessage.success('视图已保存') }
function applyView(row: any) { emit('applyView', row.query); emit('update:modelValue', false) }
async function removeView(row: any) { await ElMessageBox.confirm(`确定删除视图「${row.name}」？`, '删除视图'); await defectsApi.removeView(row.id); await loadViews() }
function saveBlob(blob: Blob, filename: string) { const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = filename; a.click(); URL.revokeObjectURL(url) }
async function downloadTemplate() { const blob: any = await defectsApi.importTemplate(); saveBlob(blob, '缺陷导入模板.xlsx') }
async function previewFile(event: Event) { const input = event.target as HTMLInputElement; const file = input.files?.[0]; if (!file) return; previewing.value = true; try { const res: any = await defectsApi.previewImport(props.projectId, createRequestId(), file); importPreview.value = res.data; importJobId.value = res.data.job_id } finally { previewing.value = false; input.value = '' } }
async function commitImport() { committing.value = true; try { const res: any = await defectsApi.commitImport(importJobId.value, { request_key: createRequestId() }); ElMessage.success(`导入完成：成功 ${res.data.success}，失败 ${res.data.failure}`); emit('refreshed') } finally { committing.value = false } }
async function exportData() { exporting.value = true; try { const cleanFilters: any = {}; for (const [key, value] of Object.entries(props.filters)) if (value && key !== 'project_id') cleanFilters[key] = value; const res: any = await defectsApi.exportDefects({ project_id: props.projectId, defect_ids: props.selectedIds, filters: cleanFilters, format: exportFormat.value, request_key: createRequestId() }); const blob: any = await defectsApi.downloadJob(res.data.id); saveBlob(blob, res.data.summary.filename) } finally { exporting.value = false } }
async function loadSettings() { const [res, people]: any = await Promise.all([defectsApi.getSettings(props.projectId), defectsApi.participants(props.projectId)]); settingParticipants.value = people.data.items; settingsForm.value = structuredClone(res.data); settingsForm.value.field_config.required_on_create ||= []; settingsForm.value.field_config.required_on_triage ||= []; settingsForm.value.permission_config.allow_reporter_edit ??= true; settingsForm.value.permission_config.allow_developer_edit_assigned ??= true; settingsForm.value.notification_config.enabled_events ||= ['*']; settingsForm.value.notification_config.default_watchers ||= []; settingsForm.value.notification_config.notify_actor ??= false }
async function saveSettings() { savingSettings.value = true; try { await defectsApi.updateSettings(props.projectId, { expected_version: settingsForm.value.row_version, timezone: settingsForm.value.timezone, field_config: settingsForm.value.field_config, permission_config: settingsForm.value.permission_config, notification_config: settingsForm.value.notification_config }); await loadSettings(); ElMessage.success('项目配置已保存') } finally { savingSettings.value = false } }
async function loadWorkflows() { const res: any = await defectsApi.workflows(props.projectId); workflows.value = res.data.items; if (!workflowId.value && workflows.value.length) workflowId.value = workflows.value[0].id }
function selectWorkflow() { draft.value = undefined; definitionText.value = '' }
async function createWorkflow() { const result: any = await ElMessageBox.prompt('工作流名称', '新建工作流', { inputValidator: (v: string) => !!v.trim() || '请输入名称' }); const res: any = await defectsApi.createWorkflow({ project_id: props.projectId, name: result.value }); await loadWorkflows(); workflowId.value = res.data.workflow_id; draft.value = { id: res.data.revision_id }; definitionText.value = JSON.stringify(res.data.definition, null, 2) }
async function createDraft() { const res: any = await defectsApi.createWorkflowDraft(workflowId.value); draft.value = res.data; definitionText.value = JSON.stringify(res.data.definition, null, 2) }
async function saveDraft() { savingDraft.value = true; try { const definition = JSON.parse(definitionText.value); const res: any = await defectsApi.updateWorkflowDraft(draft.value.id, definition); definitionText.value = JSON.stringify(res.data.definition, null, 2); ElMessage.success('草稿校验通过并已保存'); return true } catch (error: any) { if (error instanceof SyntaxError) ElMessage.error('工作流 JSON 格式不正确'); return false } finally { savingDraft.value = false } }
async function publishDraft() { await ElMessageBox.confirm('发布后版本不可修改，并将成为新缺陷的默认版本。确定发布？', '发布工作流', { type: 'warning' }); publishing.value = true; try { if (!await saveDraft()) return; await defectsApi.publishWorkflow(draft.value.id); draft.value = undefined; definitionText.value = ''; await loadWorkflows(); ElMessage.success('工作流已发布') } finally { publishing.value = false } }
async function migrateExisting() { const revision: any = await defectsApi.getWorkflowRevision(activeRevisionId.value); const states = revision.data.definition.states || []; const identity = Object.fromEntries(states.map((item: any) => [item.key, item.key])); const prompt: any = await ElMessageBox.prompt('请填写“旧状态 → 新状态”的 JSON 映射。自定义流程删除或改名状态时，请补齐所有旧状态。', '迁移已有缺陷', { inputValue: JSON.stringify(identity, null, 2), inputType: 'textarea', inputValidator: (value: string) => { try { JSON.parse(value); return true } catch { return '请输入合法 JSON' } } }); const requestKey = createRequestId(); const payload = { target_revision_id: activeRevisionId.value, state_mapping: JSON.parse(prompt.value), defect_ids: [], request_key: requestKey, preview: true }; const preview: any = await defectsApi.migrateWorkflow(props.projectId, payload); if (!preview.data.can_execute) { ElMessageBox.alert(`有 ${preview.data.errors.length} 条缺陷缺少映射，请调整 JSON 后重试。`, '迁移预检未通过', { type: 'warning' }); return } await ElMessageBox.confirm(`预检通过，将迁移 ${preview.data.items.length} 条未删除缺陷。迁移会逐条留痕，确定执行？`, '确认迁移', { type: 'warning' }); await defectsApi.migrateWorkflow(props.projectId, { ...payload, preview: false }); emit('refreshed'); ElMessage.success('已有缺陷工作流迁移完成') }
</script>

<style scoped>
.metric-cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:14px}.metric-cards span,.metric-cards small{display:block;color:var(--el-text-color-secondary)}.metric-cards strong{display:block;font-size:23px;margin:8px 0}.section-toolbar,.button-row{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:12px 0}.section-toolbar p,.transfer-grid p{font-size:13px;color:var(--el-text-color-secondary)}.section-toolbar .el-select{width:320px}.transfer-grid{display:grid;grid-template-columns:1.3fr 1fr;gap:16px}.file-button{display:inline-flex;align-items:center;border:1px solid var(--el-color-primary);color:var(--el-color-primary);border-radius:4px;padding:6px 14px;cursor:pointer;font-size:13px}.file-button input{display:none}.import-summary{display:grid;gap:12px;margin-top:14px}.error-text{color:var(--el-color-danger)}.warning-text{color:var(--el-color-warning)}.success-text{color:var(--el-color-success)}.muted{color:var(--el-text-color-secondary)}.settings-form{max-width:680px}.settings-form .el-select{width:100%}.switch-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}h3{font-size:15px;margin:18px 0 10px}@media(max-width:800px){.metric-cards{grid-template-columns:1fr 1fr}.transfer-grid,.switch-grid{grid-template-columns:1fr}}@media(max-width:520px){.metric-cards{grid-template-columns:1fr}.section-toolbar,.button-row{align-items:flex-start;flex-direction:column}.section-toolbar .el-select{width:100%}}
</style>
